+    fn truthy(&self, v: &N) -> bool {
+        match v {
+            N::U | N::Null => false,
+            N::B(b) => *b,
+            N::Num(n) => *n != 0. && !n.is_nan(),
+            N::S(s) => !s.0.is_empty(),
