+                Ok(N::Num(v.borrow().len() as f64))
+            }
+            (N::A(v), "filter") | (N::A(v), "findIndex") => {
+                let input = v.borrow().clone();
+                let mut out = vec![];
+                for (i, e) in input.into_iter().enumerate() {
+                    let yes = self.call(&a, &N::U, &[e.clone(), N::Num(i as f64), r.clone()])?;
