+                        if k == "findIndex" {
+                            return Ok(N::Num(i as f64));
+                        }
+                        out.push(e)
+                    }
+                }
+                if k == "findIndex" {
+                    Ok(N::Num(-1.))
+                } else {
+                    Ok(arr(out))
+                }
+            }
+            (N::A(v), "indexOf") => Ok(N::Num(
+                v.borrow()
