+            (N::O(_), "removeItem") => {
+                self.events.push(format!("remove:{}", string(&a)));
+                self.delete(r, &a)?;
+                Ok(N::U)
+            }
+            (N::O(_), "getItem") => self.get(r, &string(&a)),
+            (N::O(_), "setItem") => {
+                self.set(r, &a, &b)?;
+                Ok(N::U)
+            }
+            _ => Err(format!("unsupported {k}")),
+        }
+    }
+    fn parse_json_value(&mut self, v: &N) -> Result<N, String> {
